// Decide which VAT situation this invoice is in BEFORE anyone asks VIES anything.
// The invoice comes from the trigger, the customer from Read The Buyer, paired item by item.
const rules = $('VAT Rules').first().json;
const toVies = (c) => (c === 'GR' ? 'EL' : c);          // Greece is EL in VIES, GR everywhere else
const EU = String(rules.eu_country_codes || '')
  .split(',').map(s => s.trim().toUpperCase()).filter(Boolean).map(toVies);
const sellerVies = toVies(String(rules.seller_country || '').trim().toUpperCase());

const out = [];
$input.all().forEach((item, i) => {
  const customer = item.json || {};
  const ev = $('Handle Each Invoice Once').itemMatching(i).json || {};
  const inv = (ev.data && ev.data.object) ? ev.data.object : ev;

  const ids = Array.isArray(inv.customer_tax_ids) ? inv.customer_tax_ids : [];
  const euVat = ids.find(t => t && t.type === 'eu_vat' && t.value);
  const clean = euVat ? String(euVat.value).toUpperCase().replace(/[^A-Z0-9]/g, '') : '';
  const buyerCountry = String((customer.address && customer.address.country)
    || (inv.customer_address && inv.customer_address.country) || '').toUpperCase();

  let vatCountry = '';
  let vatDigits = '';
  if (clean) {
    if (/^[A-Z]{2}/.test(clean)) { vatCountry = toVies(clean.slice(0, 2)); vatDigits = clean.slice(2); }
    else { vatCountry = toVies(buyerCountry); vatDigits = clean; }   // stored without its prefix
  }
  const current = customer.tax_exempt || inv.customer_tax_exempt || 'none';
  const buyerInEU = EU.includes(toVies(buyerCountry));

  // Every rule below changes money only when the case is certain. Anything a person set on purpose,
  // or that can be legitimate outside this template's scope, is left alone or flagged, never changed.
  let kase = 'not_applicable';
  let reason = '';
  if (current === 'exempt') {
    reason = 'the customer is marked tax exempt in Stripe, a deliberate setting this workflow does not override';
  } else if (!clean) {
    if (current === 'reverse' && buyerInEU) { kase = 'stop_reverse'; reason = 'reverse charge is set for an EU buyer who has no EU VAT number on file'; }
    else if (current === 'reverse') { reason = 'reverse charge on a buyer outside your EU list (or with no address) can be legitimate, so it is left alone'; }
    else { reason = 'no EU VAT number on file, so this is not a reverse-charge sale'; }
  } else if (!EU.includes(vatCountry)) {
    reason = 'the VAT number is not from an EU country in your list, so it is left alone';
  } else if (vatCountry === sellerVies) {
    if (current === 'reverse') { kase = 'flag_domestic'; reason = 'reverse charge is set on a buyer registered in your own country. Domestic reverse charge exists only for specific goods and services, so a person should confirm it'; }
    else { reason = 'domestic sale, charge your own VAT as usual'; }
  } else {
    kase = 'check_vies';
    reason = 'cross-border EU sale to a business, the VAT number must be live today';
  }

  out.push({ json: {
    invoice_id: inv.id || null,
    invoice_status: inv.status || null,
    invoice_editable: inv.status === 'draft',
    invoice_auto_advance: inv.auto_advance === true,
    // Stripe Tax reverse-charges ANY correctly formatted tax ID "regardless of its validity"
    // (docs.stripe.com/tax/invoicing/tax-ids), so on these invoices tax_exempt is not the lever.
    stripe_tax: !!(inv.automatic_tax && inv.automatic_tax.enabled === true),
    customer_id: customer.id || inv.customer || null,
    customer_name: customer.name || inv.customer_name || '',
    customer_email: customer.email || inv.customer_email || '',
    buyer_country: buyerCountry || null,
    current_tax_exempt: current,
    vat_number: clean || null,
    vat_country: vatCountry || null,
    vat_digits: vatDigits || null,
    case: kase,
    case_reason: reason,
    attempt: 0,
    held_for_vies: false,
    livemode: inv.livemode === true,
  } });
});
return out;

// Build the VIES request. This node runs on the first attempt AND on every retry, so the attempt
// counter lives here. Sending your own VAT number is what makes VIES return a consultation number.
const rules = $('VAT Rules').first().json;
const own = String(rules.seller_vat_number || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
return $input.all().map(item => {
  const c = item.json;
  const attempt = Number(c.attempt || 0) + 1;
  const body = { countryCode: c.vat_country, vatNumber: c.vat_digits };
  if (own.length > 2) {
    const cc = own.slice(0, 2);
    body.requesterMemberStateCode = cc === 'GR' ? 'EL' : cc;
    body.requesterNumber = own.slice(2);
  }
  return { json: Object.assign({}, c, {
    attempt,
    // Only a draft that WAS going to auto-finalise counts as held by this workflow. A draft its owner
    // left manual (auto_advance false) is never switched on later, whatever VIES answers.
    held_for_vies: c.held_for_vies === true
      || (attempt > 1 && c.invoice_editable === true && c.invoice_auto_advance === true),
    vies_request: body,
  }) };
});

// Turn the VIES reply into one of four answers. The trap: a reply can say valid:false while the
// real reason is that the member state's own service is down. That is NOT an invalid number.
const rules = $('VAT Rules').first().json;
const minScore = Number(rules.name_match_minimum);
const DOWN = ['MS_UNAVAILABLE', 'SERVICE_UNAVAILABLE', 'TIMEOUT', 'MS_MAX_CONCURRENT_REQ',
  'GLOBAL_MAX_CONCURRENT_REQ', 'MS_MAX_CONCURRENT_REQ_TIME', 'GLOBAL_MAX_CONCURRENT_REQ_TIME',
  'IP_BLOCKED', 'VAT_BLOCKED'];
// Legal-form words carry no identity: GOOGLE IRELAND LIMITED and Google Ireland Ltd are one company.
const LEGAL = new Set(['LTD', 'LIMITED', 'GMBH', 'AG', 'SA', 'SAS', 'SARL', 'SRL', 'SPA', 'BV', 'NV',
  'AB', 'AS', 'OY', 'OYJ', 'PLC', 'LLC', 'INC', 'KG', 'CO', 'COMPANY', 'THE', 'AND', 'SL', 'SE', 'UG',
  'EV', 'KFT', 'ZRT', 'DOO', 'SRO', 'APS', 'ASA', 'LDA', 'EOOD', 'OOD', 'SPZOO', 'ZOO', 'SP', 'GROUP',
  // VIES often returns the legal form SPELLED OUT: ORANGE POLSKA SPOLKA AKCYJNA is Orange Polska S.A.
  'SPOLKA', 'AKCYJNA', 'OGRANICZONA', 'ODPOWIEDZIALNOSCIA', 'AKTIENGESELLSCHAFT', 'GESELLSCHAFT',
  'BESCHRANKTER', 'HAFTUNG', 'AKTIESELSKAB', 'ANPARTSSELSKAB', 'AKTIEBOLAG', 'BESLOTEN', 'NAAMLOZE',
  'VENNOOTSCHAP', 'SOCIETE', 'ANONYME', 'SIMPLIFIEE', 'SOCIETA', 'AZIONI', 'RESPONSABILITA', 'LIMITATA']);
// Some letters are not an accent on a base letter, so NFD leaves them alone and the name splits in
// two: SPOLKA with a barred L became SPO + KA. Spell them out first (Danish, Polish, Croatian, French).
const SPELL = { '\u00d8': 'O', '\u00f8': 'o', '\u00c6': 'AE', '\u00e6': 'ae', '\u0141': 'L', '\u0142': 'l', '\u0110': 'D', '\u0111': 'd', '\u0152': 'OE', '\u0153': 'oe' };
const tokens = (s) => String(s || '')
  .replace(/[\u00d8\u00f8\u00c6\u00e6\u0141\u0142\u0110\u0111\u0152\u0153]/g, ch => SPELL[ch])
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .toUpperCase().replace(/[^A-Z0-9]+/g, ' ')
  .split(' ').filter(t => t.length > 1 && !LEGAL.has(t));
// Whole-token comparison, never substring: ELECTION must not match inside SELECTION.
const dice = (a, b) => {
  const A = new Set(tokens(a)); const B = new Set(tokens(b));
  if (!A.size || !B.size) return 0;
  let hit = 0; A.forEach(t => { if (B.has(t)) hit++; });
  return (2 * hit) / (A.size + B.size);
};
const NON_LATIN = /[\u0370-\u03ff\u0400-\u04ff]/;   // Greek and Cyrillic, both returned by VIES

return $input.all().map((item, i) => {
  const c = $('Build The VIES Question').itemMatching(i).json;
  const r = item.json || {};
  const body = (r.body && typeof r.body === 'object') ? r.body : r;
  const status = Number(r.statusCode || 0);

  let result = 'unavailable';
  let error = null;
  // Three reply shapes were measured live: {valid,...}, {errorWrappers:[{error}]} and
  // {errorWrappers:[{error, message}]}. An error is about the REQUEST, never proof the buyer's number
  // is bad: a mistyped seller_vat_number returns INVALID_REQUESTER_INFO for EVERY buyer.
  const wrapped = Array.isArray(body.errorWrappers) && body.errorWrappers.length
    ? String(body.errorWrappers[0].error || 'UNKNOWN')
      + (body.errorWrappers[0].message ? ' (' + String(body.errorWrappers[0].message).slice(0, 150) + ')' : '')
    : null;
  const userError = body.userError && !['VALID', 'INVALID'].includes(String(body.userError))
    ? String(body.userError) : null;

  if (r.error) { error = 'no answer: ' + String(r.error.message || r.error).slice(0, 200); }
  else if (status >= 500) { error = 'VIES answered HTTP ' + status; }
  else if (wrapped || userError) {
    error = wrapped || userError;
    result = DOWN.includes(error.split(' ')[0]) ? 'unavailable' : 'rejected_request';
  }
  else if (body.valid === true) { result = 'valid'; }
  else if (body.valid === false) { result = 'invalid'; }
  else { error = 'VIES reply had no valid field'; }

  const viesName = (typeof body.name === 'string' && body.name.trim() && body.name.trim() !== '---')
    ? body.name.trim() : null;
  let nameCheck = null;
  let score = null;
  if (result === 'valid') {
    if (!viesName) nameCheck = 'withheld';
    else if (NON_LATIN.test(viesName)) nameCheck = 'not_comparable';
    else { score = Math.round(dice(viesName, c.customer_name) * 100) / 100; nameCheck = score >= minScore ? 'matches' : 'differs'; }
  }

  return { json: Object.assign({}, c, {
    vies_result: result,
    vies_error: error,
    vies_name: viesName,
    vies_address: (typeof body.address === 'string' && body.address.trim() !== '---') ? body.address.trim() : null,
    vies_request_id: body.requestIdentifier ? String(body.requestIdentifier) : null,
    vies_checked_at: body.requestDate ? String(body.requestDate) : new Date().toISOString(),
    name_check: nameCheck,
    name_score: score,
  }) };
});

// One decision per invoice. Items arrive from three places - the no-VIES stop path, a VIES answer,
// and a VIES that stayed down - and every one carries the same keys, so this node reads $json.
const rules = $('VAT Rules').first().json;
const holdOnChange = rules.hold_invoice_when_treatment_changes === true;
const acceptNameMismatch = rules.accept_when_name_differs === true;

return $input.all().map(item => {
  const c = Object.assign({ vies_result: null, vies_error: null, vies_name: null, vies_address: null,
    vies_request_id: null, vies_checked_at: null, name_check: null, name_score: null }, item.json);
  const current = c.current_tax_exempt || 'none';
  const stripeTax = c.stripe_tax === true;
  let target = null;
  let hold = false;
  let decision;
  let why;
  let todo = null;

  if (c.case === 'flag_domestic') {
    decision = 'flagged_domestic_reverse'; why = c.case_reason;
    todo = 'Confirm the goods or services qualify for domestic reverse charge, or set the customer to taxable.';
  } else if (c.case === 'stop_reverse') {
    target = 'none'; decision = 'reverse_charge_removed'; why = c.case_reason;
  } else if (c.vies_result === 'valid' && c.name_check === 'differs' && !acceptNameMismatch) {
    hold = true; decision = 'held_name_differs';
    why = 'VIES says ' + c.vat_number + ' is registered to "' + c.vies_name + '", not to "' + c.customer_name + '"';
    todo = 'Check which company this customer really is, correct it in Stripe, then finalise the draft.';
  } else if (c.vies_result === 'valid') {
    // Under Stripe Tax the tax ID itself drives reverse charge, so the customer is not touched.
    target = stripeTax ? null : 'reverse'; decision = 'reverse_charge_confirmed';
    why = c.name_check === 'matches' ? 'VIES confirms the number and the registered name'
      : c.name_check === 'withheld' ? 'VIES confirms the number; this member state does not publish the name'
      : c.name_check === 'not_comparable' ? 'VIES confirms the number; the registered name is not in Latin script, so it was not compared'
      : 'VIES confirms the number; the registered name differs and your rules accept that';
  } else if (c.vies_result === 'invalid') {
    decision = 'reverse_charge_refused';
    why = 'VIES says ' + c.vat_number + ' is not a valid VAT registration today';
    if (stripeTax) {
      // Stripe Tax reverse-charges any correctly formatted tax ID "regardless of its validity", so
      // setting the customer to taxable would NOT stop it. Hold, and say exactly what to remove.
      hold = true;
      todo = 'This invoice uses Stripe Tax, which reverse-charges any correctly formatted VAT number even when it is invalid. Remove tax ID ' + c.vat_number + ' from the customer, then finalise the draft.';
    } else {
      target = 'none';
    }
  } else if (c.vies_result === 'rejected_request') {
    // An error is about the REQUEST, not proof that the buyer's number is bad. Never change money on it.
    hold = true; decision = 'held_vies_rejected_request';
    why = 'VIES rejected the request (' + c.vies_error + '). If this repeats for every buyer, check seller_vat_number in VAT Rules.';
    todo = 'Check the number by hand on the VIES website, then finalise or correct the draft.';
  } else {
    hold = true; decision = 'held_vies_unavailable';
    why = 'VIES did not answer after ' + c.attempt + ' attempt(s): ' + (c.vies_error || 'no reason given');
    todo = 'Check the number by hand on the VIES website, then finalise the draft.';
  }

  const changes = target !== null && target !== current;
  if (changes && holdOnChange) hold = true;
  const editable = c.invoice_editable === true;
  const confirmedQuietly = decision === 'reverse_charge_confirmed' && !changes && c.name_check !== 'differs';
  const notify = !confirmedQuietly;

  // Proof written onto the invoice. Stripe caps a metadata value at 500 characters.
  const meta = {
    vat_decision: decision,
    vat_number_checked: c.vat_number || '',
    vies_result: c.vies_result || 'not_asked',
    vies_registered_name: c.vies_name || '',
    vies_consultation_number: c.vies_request_id || '',
    vies_checked_at: c.vies_checked_at || '',
    vat_name_check: c.name_check || '',
  };
  const parts = Object.keys(meta).map(k => 'metadata[' + k + ']=' + encodeURIComponent(String(meta[k]).slice(0, 500)));
  // Only a DRAFT can be held. Auto-finalise is switched back on ONLY for an invoice this workflow
  // held itself; a draft its owner left manual stays manual.
  if (editable && hold) parts.push('auto_advance=false');
  if (editable && !hold && c.held_for_vies === true) parts.push('auto_advance=true');

  const lines = [
    'Invoice ' + c.invoice_id + ' for ' + (c.customer_name || c.customer_id) + ' (' + (c.customer_email || 'no email') + ')',
    'Decision: ' + decision,
    'Why: ' + why,
    'VAT number checked: ' + (c.vat_number || 'none on file'),
    'Tax treatment on the customer: ' + current + (changes ? ' -> ' + target : ' (unchanged)'),
    hold ? (editable ? 'The draft invoice is HELD: it will not finalise until someone finalises it in Stripe.'
                     : 'The invoice was already ' + c.invoice_status + ', so it could not be held. Check it now.')
         : (editable ? 'The draft invoice was not held.' : 'The invoice was already ' + c.invoice_status + '; the change applies from the next invoice.'),
    c.vies_request_id ? 'VIES consultation number: ' + c.vies_request_id : 'No VIES consultation number (set seller_vat_number in VAT Rules to get one).',
    'What to do: ' + (todo || 'nothing, this is for your records.'),
  ];

  return { json: Object.assign({}, c, {
    decision,
    decision_reason: why,
    action_needed: todo,
    target_tax_exempt: target,
    treatment_changes: changes,
    hold_invoice: hold,
    notify_finance: notify,
    invoice_update_body: parts.join('&'),
    customer_update_body: target ? 'tax_exempt=' + target + '&metadata[vat_decision]=' + encodeURIComponent(decision) : '',
    email_subject: '[VAT] ' + decision.replace(/_/g, ' ') + ': ' + (c.customer_name || c.customer_id) + ', invoice ' + c.invoice_id,
    email_body: lines.join('\n'),
  }) };
});
